∀ {E : Type u_1}
  [inst : NormedAddCommGroup E] [inst_1 : InnerProductSpace ℝ E] [inst_2 : CompleteSpace E] (H : E →L[ℝ] E),
  (↑H).IsSymmetric →
    ∀ {μ : ℝ} {x : E},
      H x = μ • x →
        ∀ (h : ℝ) (N : ℕ),
          have f := fun z => inner ℝ z (H z) / 2;
          have z := (fun y => y - h • gradient f y)^[N] x;
          z = (1 - h * μ) ^ N • x ∧ ‖z‖ = |1 - h * μ| ^ N * ‖x‖ ∧ f z = (1 - h * μ) ^ (2 * N) * f x
